    }`}>
      <div className={`w-4 h-4 rounded-full ${isReady ? 'bg-green-500 animate-pulse' : 'bg-green-200'}`}></div>
      <div className={`w-4 h-4 rounded-full ${!isReady && !isRisk ? 'bg-amber-500 animate-pulse' : 'bg-amber-200'}`}></div>
