                     <div className="prose prose-invert prose-sm max-w-none whitespace-pre-wrap">
                        {advisory}
                     </div>
                  ) : (
                     <div className="text-center pt-8 opacity-50 px-4">
                        <p className="text-xs">Run analysis to generate a strategic v3.0 Auditor Report.</p>
                     </div>
