                </div>
            </div>
            <p className="text-[10px] text-slate-500 mt-2">
                *Based on EDGE User Guide Part 8, Table 10. For apartments, calculate per typology. For Retail/Office, verify 40% of similar areas.
            </p>
        </div>
    );
};

