    input.type = 'file';
    input.accept = '.pdf,.png,.jpg';
    input.onchange = (e: any) => {
       if (e.target.files.length > 0) {
          setEvidenceCount(c => c + 1);
          alert("Document uploaded successfully and linked to compliance record.");
       }
    };
    input.click();
