import React, { useState } from 'react';
import { 
  ShieldCheck, Lock, Building2, FileCheck, Globe, 
  ChevronRight, Check, AlertTriangle, Fingerprint, Smartphone, Mail, Loader2
} from 'lucide-react';
import { User } from '../types';
import { supabase } from '../lib/supabaseClient';

interface AuthProps {
  onLogin: (user: User) => void;
}

const STEPS = [
  { id: 1, label: 'Identity' },
  { id: 2, label: 'Organization' },
  { id: 3, label: 'Compliance' },
  { id: 4, label: 'Security' }
];

const ISO_STANDARDS = [
  { id: 'iso14001', label: 'ISO 14001 (Environment)', icon: Globe },
  { id: 'iso9001', label: 'ISO 9001 (Quality)', icon: FileCheck },
  { id: 'iso27001', label: 'ISO 27001 (Security)', icon: Lock },
  { id: 'esg', label: 'ESG Reporting', icon: Building2 },
];

export const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    fullName: '',
    orgName: '',
    role: 'manager',
    jurisdiction: 'USA',
    standards: [] as string[],
    mfaMethod: 'app'
  });

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: formData.email,
        password: formData.password,
      });

      if (error) throw error;

      // onLogin will be handled by the session listener in App.tsx
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Login failed');
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: window.location.origin
        }
      });
      if (error) throw error;
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Google login failed');
      setLoading(false);
    }
  };

  const handleNextStep = () => {
    setError(null);

    // Step 1 Validation: Identity
    if (step === 1) {
      if (!formData.fullName.trim()) {
        setError("Please enter your full legal name.");
        return;
      }
      if (!formData.email.trim()) {
        setError("Please enter your work email.");
        return;
      }
      // Simple email format check
