import { createClient } from '@supabase/supabase-js';

// Access environment variables securely. 
// Fallback to empty strings ensures the app doesn't crash on import, 
// though actual requests will fail if keys are invalid (handled by try/catch blocks in components).
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || '';
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY || '';

if (!supabaseUrl || !supabaseAnonKey) {
  console.warn("Supabase URL or Key is missing. Please check your .env file.");
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  }
});

