         `"${log.action.replace(/"/g, '""')}"`, // Escape quotes
         log.user,
         log.role,
         new Date(log.timestamp).toLocaleString(),
         log.status
      ]);
      const csvContent = [
         headers.join(','),
         ...rows.map(r => r.join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
