            {/* FOOTER: EVIDENCE UPLOAD (Always visible on Calculator/Auditor) */}
            {activeTab !== 'bim' && activeTab !== 'plan' && activeTab !== 'trail' && (
              <div className="p-4 border-t border-slate-200 bg-slate-50 flex justify-between items-center">
