import { createClient } from '@supabase/supabase-js';

// Access environment variables securely.
// We use a safe access pattern because import.meta.env might be undefined in some environments.
const meta = import.meta as any;
const env = meta.env || {};

// Use placeholders if environment variables are missing to prevent createClient from throwing immediately.
