         'postgres_changes',
         { event: '*', schema: 'public', table: 'waste_manifests' },
         (payload) => {
            if (payload.eventType === 'INSERT') {
              setManifests(prev => [payload.new, ...prev]);
            } else if (payload.eventType === 'UPDATE') {
              setManifests(prev => prev.map(m => m.id === payload.new.id ? payload.new : m));
            }
         }
       )
