const Dashboard: React.FC<DashboardProps> = ({ initialRole = 'manager' }) => {
  const [role, setRole] = useState(initialRole);

  // Sync role if prop updates (e.g. login)
  useEffect(() => {
    setRole(initialRole);
  }, [initialRole]);

  const renderDashboard = () => {
    switch (role) {
      case 'manager': return <SiteManagerView />;
