export const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    signupPassword: '', // New field for signup
    fullName: '',
    orgName: '',
    role: 'manager',
    jurisdiction: 'USA',
    standards: [] as string[],
    mfaMethod: 'app'
  });

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    // Explicit offline/demo mode check
    if (isOffline) {
       setTimeout(() => {
         onLogin({
            name: 'Demo User',
            email: formData.email,
            role: 'manager',
            organization: 'Demo Mode',
            jurisdiction: 'USA',
            standards: []
         });
       }, 1000);
       return;
    }

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: formData.email,
        password: formData.password,
      });

      if (error) throw error;

      // onLogin will be handled by the session listener in App.tsx
    } catch (err: any) {
      console.error(err);
      // Catch "Failed to fetch" specifically to allow access even if backend is unreachable
      if (err.message === 'Failed to fetch' || err.message?.includes('NetworkError')) {
          setTimeout(() => {
             onLogin({
                name: 'User (Offline)',
                email: formData.email,
                role: 'manager',
                organization: 'Offline Mode',
                jurisdiction: 'USA',
                standards: []
             });
          }, 1000);
          return;
      }
      setError(err.message || 'Login failed');
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: window.location.origin
        }
      });
      if (error) throw error;
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Google login failed');
      setLoading(false);
    }
  };

  const handleNextStep = () => {
    setError(null);

    // Step 1 Validation: Identity
    if (step === 1) {
      if (!formData.fullName.trim()) {
        setError("Please enter your full legal name.");
        return;
      }
      if (!formData.email.trim()) {
        setError("Please enter your work email.");
        return;
      }
      if (!formData.signupPassword || formData.signupPassword.length < 8) {
        setError("Please enter a password of at least 8 characters.");
        return;
      }
      // Simple email format check
      if (!/^\S+@\S+\.\S+$/.test(formData.email)) {
        setError("Please enter a valid email address.");
        return;
      }
    }

    // Step 2 Validation: Organization
    if (step === 2) {
      if (!formData.orgName.trim()) {
        setError("Organization Name is required.");
        return;
      }
    }

    // Proceed if valid
    setStep(step + 1);
  };

  const handleSignupComplete = async () => {
    setLoading(true);
    setError(null);

    // Explicit offline/demo mode check
    if (isOffline) {
       setTimeout(() => {
         onLogin({
            name: formData.fullName,
            email: formData.email,
            role: formData.role,
            organization: formData.orgName,
            jurisdiction: formData.jurisdiction,
            standards: formData.standards
         });
       }, 1500);
       return;
    }

    try {
      const { data, error } = await supabase.auth.signUp({
        email: formData.email,
        password: formData.signupPassword,
        options: {
          data: {
            full_name: formData.fullName,
            role: formData.role,
            organization: formData.orgName,
            jurisdiction: formData.jurisdiction,
            standards: formData.standards
          }
        }
      });

      if (error) throw error;

      // Auto-login happens on signup usually, App.tsx listener will catch it
    } catch (err: any) {
      console.error(err);
      // Catch "Failed to fetch" specifically to allow access even if backend is unreachable
      if (err.message === 'Failed to fetch' || err.message?.includes('NetworkError')) {
          setTimeout(() => {
             onLogin({
                name: formData.fullName,
                email: formData.email,
                role: formData.role,
                organization: formData.orgName,
                jurisdiction: formData.jurisdiction,
                standards: formData.standards
             });
          }, 1500);
          return;
      }

      setError(err.message || 'Signup failed');
      setLoading(false);
    }
  };

  const toggleStandard = (id: string) => {
    setFormData(prev => ({
      ...prev,
      standards: prev.standards.includes(id) 
        ? prev.standards.filter(s => s !== id)
        : [...prev.standards, id]
    }));
  };

  const handleShowLegal = (e: React.MouseEvent, type: 'terms' | 'privacy') => {
      e.preventDefault();
      // Since Auth is outside main app context, we use a simple alert or modal approach here
      // For this demo, a simple alert suffices to show interactivity, or we could add a state for a modal.
      alert(`${type === 'terms' ? 'Terms of Service' : 'Privacy Policy'} content would appear here in a production environment.`);
  };

  // Background Pattern Styles (Data Mesh / Hexagon Grid)
