import React, { useState } from 'react';
import { 
  ShieldCheck, Lock, Building2, FileCheck, Globe, 
  ChevronRight, Check, AlertTriangle, Fingerprint, Smartphone, Mail, Loader2
} from 'lucide-react';
import { User } from '../types';
import { supabase, isOffline } from '../lib/supabaseClient';

interface AuthProps {
  onLogin: (user: User) => void;
}

const STEPS = [
  { id: 1, label: 'Identity' },
  { id: 2, label: 'Organization' },
  { id: 3, label: 'Compliance' },
  { id: 4, label: 'Security' }
];

const ISO_STANDARDS = [
  { id: 'iso14001', label: 'ISO 14001 (Environment)', icon: Globe },
  { id: 'iso9001', label: 'ISO 9001 (Quality)', icon: FileCheck },
  { id: 'iso27001', label: 'ISO 27001 (Security)', icon: Lock },
  { id: 'esg', label: 'ESG Reporting', icon: Building2 },
];

export const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    signupPassword: '', // New field for signup
    fullName: '',
    orgName: '',
    role: 'manager',
    jurisdiction: 'USA',
    standards: [] as string[],
    mfaMethod: 'app'
  });

  const triggerDemoLogin = (name: string, email: string) => {
    // Helper to simulate login delay then enter app
    setTimeout(() => {
        onLogin({
           name: name || 'Demo User',
           email: email,
           role: formData.role,
           organization: formData.orgName || 'Demo Organization',
           jurisdiction: formData.jurisdiction,
           standards: formData.standards
        });
    }, 1000);
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    // 1. Explicit offline check
    if (isOffline) {
       triggerDemoLogin('Demo User', formData.email);
       return;
    }

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: formData.email,
        password: formData.password,
      });

      if (error) throw error;

      // onLogin will be handled by the session listener in App.tsx
    } catch (err: any) {
      console.error(err);

      // 2. Catch Network/Fetch errors (Implicit offline check)
      const msg = err.message || '';
      if (
          msg === 'Failed to fetch' || 
          msg.includes('NetworkError') || 
          msg.includes('fetch') ||
          msg.includes('connection')
      ) {
          console.warn("Backend unreachable. Falling back to Demo Mode.");
          triggerDemoLogin('User (Offline)', formData.email);
          return;
      }

      setError(msg || 'Login failed');
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: window.location.origin
        }
      });
      if (error) throw error;
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Google login failed');
      setLoading(false);
    }
  };

  const handleNextStep = () => {
    setError(null);

    // Step 1 Validation: Identity
    if (step === 1) {
      if (!formData.fullName.trim()) {
        setError("Please enter your full legal name.");
        return;
      }
      if (!formData.email.trim()) {
        setError("Please enter your work email.");
        return;
      }
      if (!formData.signupPassword || formData.signupPassword.length < 8) {
        setError("Please enter a password of at least 8 characters.");
        return;
      }
      // Simple email format check
      if (!/^\S+@\S+\.\S+$/.test(formData.email)) {
        setError("Please enter a valid email address.");
        return;
      }
    }

    // Step 2 Validation: Organization
    if (step === 2) {
      if (!formData.orgName.trim()) {
        setError("Organization Name is required.");
        return;
      }
    }

    // Proceed if valid
    setStep(step + 1);
  };

  const handleSignupComplete = async () => {
    setLoading(true);
    setError(null);

    // 1. Explicit offline check
    if (isOffline) {
       triggerDemoLogin(formData.fullName, formData.email);
       return;
    }

    try {
      const { data, error } = await supabase.auth.signUp({
        email: formData.email,
        password: formData.signupPassword,
        options: {
          data: {
            full_name: formData.fullName,
            role: formData.role,
            organization: formData.orgName,
            jurisdiction: formData.jurisdiction,
            standards: formData.standards
          }
        }
      });

      if (error) throw error;

      // Auto-login happens on signup usually, App.tsx listener will catch it
    } catch (err: any) {
      console.error("Signup error:", err);

      // 2. Catch Network/Fetch errors (Implicit offline check)
      const msg = err.message || '';
      if (
          msg === 'Failed to fetch' || 
          msg.includes('NetworkError') || 
          msg.includes('fetch') ||
          msg.includes('connection')
      ) {
          console.warn("Backend unreachable. Falling back to Demo Mode.");
          triggerDemoLogin(formData.fullName, formData.email);
          return;
      }

      setError(msg || 'Signup failed');
      setLoading(false);
    }
  };

  const toggleStandard = (id: string) => {
    setFormData(prev => ({
      ...prev,
      standards: prev.standards.includes(id) 
        ? prev.standards.filter(s => s !== id)
        : [...prev.standards, id]
    }));
  };

  const handleShowLegal = (e: React.MouseEvent, type: 'terms' | 'privacy') => {
